const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const denmark = ee.FeatureCollection("FAO/GAUL/2015/level0")
    .filter(ee.Filter.eq("ADM0_NAME", "Denmark"));

  const july2017 = ee.DateRange("2017-07-01", "2017-07-31");
  const july2018 = ee.DateRange("2018-07-01", "2018-07-31");

  // 2. Data Acquisition - Sentinel-2 for NDVI
  function getMonthlyNDVI(dateRange) {
    let col = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")
      .filterBounds(denmark)
      .filterDate(dateRange.start(), dateRange.end())
      .select(["B4", "B8"]); // Red, NIR for NDVI

    if (col.size().getInfo() === 0) {
      // Fallback to Landsat 8 if Sentinel-2 empty
      col = ee.ImageCollection("LANDSAT/LC08/C02/T1_L2")
        .filterBounds(denmark)
        .filterDate(dateRange.start(), dateRange.end())
        .select(["SR_B4", "SR_B5"]);
    }

    if (col.size().getInfo() === 0) {
      return null;
    }

    // Cloud masking for Sentinel-2
    if (col.get("system:id").getInfo().includes("S2")) {
      col = col.map(function(img) {
        const qa = img.select("QA60");
        const cloudBitMask = 1 << 10;
        const cirrusBitMask = 1 << 11;
        const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
          .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
        return img.updateMask(mask);
      });
    }

    // Calculate NDVI: (NIR - Red) / (NIR + Red)
    const ndviCol = col.map(function(img) {
      let nir, red;
      if (img.bandNames().getInfo().includes("B8")) { // Sentinel-2
        nir = img.select("B8");
        red = img.select("B4");
      } else { // Landsat 8
        nir = img.select("SR_B5").multiply(0.0000275).add(-0.2);
        red = img.select("SR_B4").multiply(0.0000275).add(-0.2);
      }
      return nir.subtract(red).divide(nir.add(red)).rename("NDVI");
    });

    return ndviCol.mean().clip(denmark);
  }

  // Get NDVI images
  const ndvi2017 = getMonthlyNDVI(july2017);
  const ndvi2018 = getMonthlyNDVI(july2018);

  // Check for empty collections
  if (!ndvi2017 || !ndvi2018) {
    const count2017 = ndvi2017 ? ">0" : "0";
    const count2018 = ndvi2018 ? ">0" : "0";
    console.log(`2017 Images: ${count2017}, 2018 Images: ${count2018}`);
    console.log("<answer>C1</answer>");
    return;
  }

  // 3. Calculate browning (decrease in NDVI = increase in browning)
  const browning = ndvi2017.subtract(ndvi2018).rename("browning");

  // 4. Validate pixel counts
  const countStats = browning.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: denmark,
    scale: 1000,
    maxPixels: 1e9,
  });
  const pixelCount = countStats.get("browning").getInfo();

  if (pixelCount === 0) {
    console.log("Valid pixels: 0");
    console.log("<answer>C2</answer>");
    return;
  }

  // 5. Calculate mean browning
  const browningStats = browning.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: denmark,
    scale: 1000,
    maxPixels: 1e9,
  });
  const meanBrowning = browningStats.get("browning").getInfo();

  // 6. Validation & Final Answer
  console.log(`Mean Browning (NDVI decrease): ${meanBrowning?.toFixed(4)}`);
  console.log(`Valid pixels: ${pixelCount}`);

  if (meanBrowning === null || meanBrowning === undefined || 
      isNaN(meanBrowning) || Math.abs(meanBrowning) > 2) {
    console.log("<answer>C3</answer>");
  } else if (meanBrowning > 0) {
    // NDVI decreased from 2017 to 2018 = browning increased
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
